      "remediation": {
        "summary": "Require authorization, make destruction recoverable, and gate it behind an explicit human confirmation. Annotate the tool as destructive so clients can surface the risk before calling it.",
        "config": "from mcp.types import ToolAnnotations

@server.tool(
    description="Move a document to the recycle bin after human confirmation.",
    annotations=ToolAnnotations(destructiveHint=True, idempotentHint=False),
)
def delete_file(path: str, token: str, confirm: bool = False) -> str:
    role = _verify(token)
    if role not in {"admin", "records"}:
        raise PermissionError("not permitted to delete")
    if not confirm:
        return "refused: destructive operation requires confirm=True (HITL gate)"
    target = (STORE / path).resolve()
    if not target.is_relative_to(STORE.resolve()):
        raise ValueError("path escapes store")
    target.rename(RECYCLE / target.name)   # recoverable, not unlink
    return f"moved {path} to recycle bin"",
        "guardrail": "A destructiveHint-aware client policy that refuses to auto-execute destructive tools without an interactive confirmation, plus a retention window on the recycle bin."
